def _write_case(url: str, raw: bool = False) -> str:
    """生成与 cases/health.json 同构、仅覆盖 url 的临时用例文件。

    raw=True 时把查询中的原始空格改写为 JSON 转义字面量  ，
    用于验证转义还原后的空格与直接书写结果一致。
    """
    case = {
        "name": "health",
        "url": url,
        "expected_status": 200,
        "field": "status",
        "expected_value": "ok",
    }
    fd, path = tempfile.mkstemp(suffix=".json")
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        if raw:
            handle.write("{" + ", ".join(
                _encode_case_parts(case)
            ) + "}")
        else:
            json.dump(case, handle, ensure_ascii=False)
    return path


def _encode_case_parts(case: dict) -> list[str]:
    parts = []
    for key, value in case.items():
        if isinstance(value, str):
            encoded = json.dumps(value, ensure_ascii=False).replace(" ", r" ")
            parts.append(f"{json.dumps(key)}: {encoded}")
        else:
            parts.append(f"{json.dumps(key)}: {json.dumps(value)}")
    return parts
